// Runtime UI translation. The app's markup and scripts stay in English;
// this layer swaps whole UI strings (text nodes and title/placeholder/
// aria-label/alt attributes) using static/i18n/<lang>.json, generated by
// scripts/i18n_extract.py. Keys containing {0}, {1}… are matched as patterns.
// Chat content is never rewritten, except a message paragraph that is exactly
// a known system phrase. Load it as a classic <script> in <head>: it picks the
// language (saved choice, else browser language) and sets <html lang> before
// first paint so :lang() rules apply immediately.
(function () {
  const SUPPORTED = { 'pt-BR': 'Português (BR)', en: 'English', es: 'Español' };
  const LS_KEY = 'odysseus-ui-lang';

  function pickLang() {
    let saved = null;
    try { saved = localStorage.getItem(LS_KEY); } catch (_) {}
    if (saved && SUPPORTED[saved]) return saved;
    const nav = (navigator.languages && navigator.languages[0]) || navigator.language || 'en';
    if (/^pt/i.test(nav)) return 'pt-BR';
    if (/^es/i.test(nav)) return 'es';
    return 'en';
  }

  const lang = pickLang();
  document.documentElement.lang = lang;

  window.OdysseusI18n = {
    lang,
    supported: SUPPORTED,
    setLang(next) {
      if (!SUPPORTED[next] || next === lang) return;
      try { localStorage.setItem(LS_KEY, next); } catch (_) {}
      location.reload();
    },
  };

  function wirePicker() {
    const card = document.getElementById('uiLangCard');
    if (!card || card.dataset.bound === '1') return;
    card.dataset.bound = '1';
    card.querySelectorAll('[data-ui-lang]').forEach((b) => {
      const on = b.dataset.uiLang === lang;
      b.classList.toggle('active', on);
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
      b.addEventListener('click', () => window.OdysseusI18n.setLang(b.dataset.uiLang));
    });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', wirePicker, { once: true });
  else wirePicker();

  if (lang === 'en') return;

  const DEFAULT_BRAND = 'Odysseus';
  const brandMeta = document.querySelector('meta[name="app-brand"]');
  const brand = (brandMeta && brandMeta.content.trim()) || DEFAULT_BRAND;
  const ATTRS = ['title', 'placeholder', 'aria-label', 'alt'];
  const SKIP = 'script, style, code, pre, textarea, [contenteditable="true"], [translate="no"], .msg-user .body, '
    + '.ProseMirror, .cm-editor, .document-editor, .doc-editor, .note-editor, .email-body';

  const exact = new Map();
  const byFirstWord = new Map();
  const leading = [];

  function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

  function addPattern(key, value) {
    const order = [];
    const re = new RegExp('^' + key.split(/(\{\d+\})/).map((part) => {
      const m = part.match(/^\{(\d+)\}$/);
      if (m) { order.push(m[1]); return '(.+?)'; }
      return escapeRe(part);
    }).join('') + '$');
    const entry = { re, order, value, size: key.length };
    const first = key.match(/^([^\s{]+)/);
    if (!first) { leading.push(entry); return; }
    const list = byFirstWord.get(first[1]) || [];
    list.push(entry);
    byFirstWord.set(first[1], list);
  }

  function fromBrand(s) { return brand === DEFAULT_BRAND ? s : s.split(brand).join(DEFAULT_BRAND); }
  function toBrand(s) { return brand === DEFAULT_BRAND ? s : s.split(DEFAULT_BRAND).join(brand); }

  function lookup(text, allowPatterns) {
    const key = fromBrand(text.replace(/\s+/g, ' ').trim());
    if (!key || key.length > 400) return null;
    const hit = exact.get(key);
    if (hit !== undefined) return toBrand(hit);
    if (!allowPatterns) return null;
    const first = key.match(/^([^\s]+)/);
    const candidates = (first && byFirstWord.get(first[1])) || [];
    for (const p of candidates.concat(leading)) {
      const m = p.re.exec(key);
      if (!m) continue;
      let out = p.value;
      p.order.forEach((idx, i) => { out = out.split('{' + idx + '}').join(m[i + 1]); });
      return toBrand(out);
    }
    return null;
  }

  function translateText(node) {
    const parent = node.parentElement;
    const raw = node.nodeValue;
    if (!parent || !raw || !raw.trim() || parent.closest(SKIP)) return;
    const inMessage = parent.closest('.msg .body');
    if (inMessage && parent !== inMessage && !/^(P|LI|SPAN|STRONG|EM)$/.test(parent.tagName)) return;
    // A lone word in a reply or chat title is user content ("Absolutely", "Chat").
    if ((inMessage || parent.closest('.session-item .grow')) && !/\s/.test(raw.trim())) return;
    const out = lookup(raw, true);
    if (out === null || out === raw.trim()) return;
    const lead = raw.match(/^\s*/)[0];
    const trail = raw.match(/\s*$/)[0];
    node.nodeValue = lead + out + trail;
  }

  function translateAttrs(el) {
    if (!el.getAttribute || (el.closest && el.closest('.msg .body'))) return;
    for (const a of ATTRS) {
      const v = el.getAttribute(a);
      if (!v) continue;
      const out = lookup(v, true);
      if (out !== null && out !== v) el.setAttribute(a, out);
    }
  }

  function walk(root) {
    if (root.nodeType === Node.TEXT_NODE) { translateText(root); return; }
    if (root.nodeType !== Node.ELEMENT_NODE) return;
    translateAttrs(root);
    const tw = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
    let n = tw.nextNode();
    while (n) {
      if (n.nodeType === Node.TEXT_NODE) translateText(n); else translateAttrs(n);
      n = tw.nextNode();
    }
  }

  function translateTitle() {
    const out = lookup(document.title, true);
    if (out !== null && out !== document.title) document.title = out;
  }

  function start(dict) {
    for (const [k, v] of Object.entries(dict || {})) {
      if (typeof v !== 'string' || !v) continue;
      if (/\{\d+\}/.test(k)) addPattern(k, v); else exact.set(k, v);
    }
    for (const list of byFirstWord.values()) list.sort((a, b) => b.size - a.size);
    leading.sort((a, b) => b.size - a.size);
    const run = () => {
      walk(document.body);
      translateTitle();
      new MutationObserver((records) => {
        for (const r of records) {
          if (r.type === 'childList') r.addedNodes.forEach(walk);
          else if (r.type === 'characterData') translateText(r.target);
          else if (r.type === 'attributes') translateAttrs(r.target);
        }
      }).observe(document.body, {
        childList: true, subtree: true, characterData: true,
        attributes: true, attributeFilter: ATTRS,
      });
      const titleEl = document.querySelector('title');
      if (titleEl) new MutationObserver(translateTitle).observe(titleEl, { childList: true, characterData: true, subtree: true });
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run, { once: true });
    else run();
  }

  fetch('/static/i18n/' + lang + '.json', { credentials: 'same-origin', cache: 'no-cache' })
    .then((r) => (r.ok ? r.json() : {}))
    .then(start)
    .catch(() => {});
})();
